-- ============================================================
-- Woxsen Champions League, Season 1 -- the real tournament data.
--
--   12 teams  ·  107 players  ·  2 groups of 6  ·  30 group matches
--
-- Sources (kept in the repo so this file can always be rebuilt):
--   docs/teamlist.md  -- squads and captains
--   docs/fixtures.md  -- the group schedule
--
-- Two deliberate gaps:
--   * No jersey numbers. The team list does not record them, and inventing
--     them would be inventing data. The column is nullable on purpose.
--   * No knockout matches. The semi-finals and final on Thursday 3 September
--     are "Winner Group A v Runner-up Group B" and so on -- they have no
--     teams yet, and matches.home_team_id is NOT NULL. Create them from
--     /admin/fixtures once the group stage is decided.
--
-- Positions: the team list writes CF; the schema enum is GK/DEF/MID/FWD, so
-- every CF is stored as FWD and renders as "Forward" on the site.
--
-- Kit: teams have no colour of their own. The side listed at home wears
-- dark and the away side wears light, which is exactly what the black and
-- white boxes on the fixture sheet mean -- so the home/away order of every
-- row below is the kit, and getting it backwards puts a team in the wrong
-- shirt. See src/lib/kit.ts.
--
-- All kickoff times are the campus clock (IST, +05:30) as printed on the
-- fixture sheet, written with an explicit offset so the zone is unambiguous.
--
-- Safe to re-run: it clears the tournament tables first.
-- ============================================================

begin;

delete from cards;
delete from goals;
delete from matches;
delete from players;
delete from teams;

